#include <stdio.h>
#include <string.h>
#include <stdlib.h>

#define OUT_BUF_SIZE 1024   /* 0x400 */

static void to_camel(const char *in, char *out)
{
    int capitalize = 0;          /* set after an '_' */
    size_t pos = 0;              /* output position */

    while (*in) {
        if (*in == '_') {
            capitalize = 1;      /* next character should be upper case */
        } else {
            char c = *in;
            if (capitalize && c >= 'a' && c <= 'z')
                c = (char)(c - ('a' - 'A'));   /* to upper case */
            if (pos + 1 < OUT_BUF_SIZE) {      /* keep space for NUL */
                out[pos++] = c;
            }
            capitalize = 0;
        }
        ++in;
    }
    out[pos] = '\0';
}

static void to_snake(const char *in, char *out)
{
    size_t pos = 0;              /* output position */
    int first = 1;               /* true for the very first character */

    while (*in) {
        char c = *in;
        if (c >= 'A' && c <= 'Z') {
            if (!first) {
                if (pos + 1 < OUT_BUF_SIZE) {   /* '_' */
                    out[pos++] = '_';
                }
            }
            c = (char)(c + ('a' - 'A'));        /* to lower case */
        }
        if (pos + 1 < OUT_BUF_SIZE) {
            out[pos++] = c;
        }
        first = 0;
        ++in;
    }
    out[pos] = '\0';
}

int main(int argc, char **argv)
{
    char out[OUT_BUF_SIZE];

    if (argc < 3) {
        puts("USAGE");
        return 0;
    }

    if (strcmp(argv[1], "to_camel") == 0) {
        to_camel(argv[2], out);
        puts(out);
    } else if (strcmp(argv[1], "to_snake") == 0) {
        to_snake(argv[2], out);
        puts(out);
    } else {
        puts("INVALID_MODE");
    }

    return 0;
}
